SELECT TRUNC(a.APPLICATION_DATE,'MM') APPLICATION_MONTH, a.FINANCIER_ID, o.ORG_NAME_AR FINANCIER_NAME_AR, o.ORG_TYPE_CODE, a.STATUS_CODE, s.NAME_AR STATUS_NAME_AR, COUNT(*) APPLICATION_COUNT, SUM(NVL(a.REQUESTED_FINANCE_AMOUNT,0)) REQUESTED_AMOUNT, SUM(NVL(a.APPROVED_FINANCE_AMOUNT,0)) APPROVED_AMOUNT FROM MFF_APPLICATIONS a JOIN MFF_ORGANIZATIONS o ON o.ORG_ID=a.FINANCIER_ID JOIN REF_MFF_APPLICATION_STATUS s ON s.CODE=a.STATUS_CODE GROUP BY TRUNC(a.APPLICATION_DATE,'MM'),a.FINANCIER_ID,o.ORG_NAME_AR,o.ORG_TYPE_CODE,a.STATUS_CODE,s.NAME_AR;
